/* Square preloader animation 
--------------------------------------------- */
@keyframes preloader-square {
  0% {
    transform: rotate(0deg);
  }
  25% {
    transform: rotate(180deg);
  }
  50% {
    transform: rotate(180deg);
  }
  75% {
    transform: rotate(360deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
@keyframes preloader-square-inner {
  0% {
    height: 0;
  }
  25% {
    height: 0;
  }
  50% {
    height: 100%;
  }
  75% {
    height: 100%;
  }
  100% {
    height: 0;
  }
}
/* Dots preloader animation 
--------------------------------------------- */
@keyframes preloader-dots-one {
  0% {
    transform: scale(0);
  }
  100% {
    transform: scale(1);
  }
}
@keyframes preloader-dots-two {
  0% {
    transform: translate(0, 0);
  }
  100% {
    transform: translate(2em, 0);
  }
}
@keyframes preloader-dots-three {
  0% {
    transform: scale(1);
  }
  100% {
    transform: scale(0);
  }
}
/* Circle preloader animation 
--------------------------------------------- */
@keyframes preloader-circle {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
/* Dotted square preloader animation 
--------------------------------------------- */
@keyframes preloader-dots-circle {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.25;
  }
}
/* Classic preloader animation 
--------------------------------------------- */
@keyframes preloader-classic {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}
/* Multiline preloader animation 
--------------------------------------------- */
@keyframes preloader-multiline {
  0% {
    opacity: 0.15;
    width: 0%;
  }
  20% {
    width: 100%;
  }
  39% {
    opacity: 0.15;
  }
  40% {
    opacity: 0.05;
    width: 0%;
  }
  60% {
    width: 100%;
  }
  80% {
    width: 0%;
  }
  100% {
    opacity: 0.05;
    width: 0%;
  }
}
@keyframes loaderAlt {
  0% {
    opacity: 0.07;
    width: 100%;
  }
  19% {
    opacity: 0.07;
  }
  20% {
    opacity: 0.1;
    width: 0%;
  }
  40% {
    width: 100%;
  }
  59% {
    opacity: 0.1;
  }
  60% {
    opacity: 0.07;
    width: 0;
  }
  80% {
    width: 100%;
  }
  100% {
    opacity: 0.07;
    width: 100%;
  }
}
/* Line preloader animation 
--------------------------------------------- */
@keyframes preloader-line {
  0% {
    transform: translateX(-100%);
  }
  40% {
    transform: translateX(0);
  }
  60% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(100%);
  }
}
