  content: "";
}
.media-box.quote p:before {
  content: "";
}
.media-box .media-box-caption {
  position: absolute;
  bottom: 0;
  right: 0;
  padding: 0.25em 1em;
  background: rgba(255, 255, 255, 0.8);
}

