/* Footer widget style 
------------------------------------------------------------------ */
.site-footer-widgets {
  color: var(--footer-widgets-color, var(--primary-color));
  background-color: var(--footer-widgets-background-color, var(--secondary-color));
}

/* 404 style 
------------------------------------------------------------------ */
body.error404 .error-404 {
